mapper.select:
select count(*)
from dm_change
where owner_uid = #{ownerUid}
  and ref_flow_id = #{flowId}
  and lock_status = 0

mapper.update:
update dm_change
set schedule_time = now(),
    version       = version + 1
where id = #{changeId}
  and version = #{version}

update dm_change
set schedule_time = now(),
    version       = version + 1,
    try_times     = try_times + 1,
    remark        = #{remark}
where id = #{changeId}
  and version = #{version}

update dm_change
set schedule_time  = now(),
    version        = version + 1,
    remark         = #{remark},
    current_status = #{toStatus, javaType=com.clougence.clouddm.platform.dal.model.cicd.ChangeStatus}
where id = #{changeId}
  and version = #{version}

update dm_change
set schedule_time = now(),
    version       = version + 1,
    try_times     = 0,
    remark        = #{remark},
    current_step  = #{toStep, javaType=com.clougence.clouddm.platform.dal.model.cicd.ChangeStep}
where id = #{changeId}
  and version = #{version}

update dm_change
set version     = version + 1,
    lock_status = 1
where id = #{changeId}
  and version = #{version}
